contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take an amount to send when calling wager, and a dummy whale address is already set in C's constructor.
    // This test will: open contract to public (onlyOwner) via the deploying owner (InvMutTest) won't be owner,
    // so instead we rely on the fact that the checker deploys C and passes it here; to ensure openToPublic is true,
    // we call OpenToThePublic through the c contract with a try/catch and record whether it reverted.
    // Then we attempt to wager (should succeed only if open and amount==betLimit). Finally we call play()
    // and assert that when wager succeeded in this transaction, play() must revert because timestamps[msg.sender]==block.number.

    receive() external payable {}

    function run(uint256 amount) public payable {
        require(true);

        // Try to open to public. This may revert if InvMutTest is not owner; record success but don't fail.
        bool opened = false;
        try c.OpenToThePublic() {
            opened = true;
        } catch {
            opened = false;
        }

        // Read current bet limit to know what wager expects
        uint256 beforeBetLimit = c.currentBetLimit();

        bool wagerReverted = false;
        // If we plan to send Ether, ensure balance
        if (amount > 0) {
            require(address(this).balance >= amount, "not enough balance to send");
        }

        // Attempt to call wager with given amount passed as value. Capture whether it reverts.
        try c.wager{value: amount}() {
            wagerReverted = false;
        } catch {
            wagerReverted = true;
        }

        // Attempt to call play and see if it reverts.
        bool playReverted = false;
        try c.play() {
            playReverted = false;
        } catch {
            playReverted = true;
        }

        // General rule asserted:
        // If wager call did NOT revert in this transaction, then two necessary conditions must have held:
        // 1) amount == beforeBetLimit (wager requires msg.value == betLimit), and
        // 2) play() must revert when called immediately after (because timestamps[msg.sender] was set to current block number by wager,
        //    and play requires stored block number < block.number).
        assert( wagerReverted || (amount == beforeBetLimit && playReverted) );
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We'll test the donate() public function: when it is callable (openToPublic must be true),
    // calling donate() with `amount` should forward the amount to the whale and thus reduce c's balance by `amount`.
    // We observe this via address(c).balance and winnersPot().
    function run(uint256 amount) public payable {
        require(amount > 0);
        // Ensure this contract has enough ETH to forward
        require(address(this).balance >= amount);

        // Open contract to public (owner-only). The InvMutTest is the deployer of c, so it is owner.
        c.OpenToThePublic();

        // Read balances and winners pot before the donation
        uint256 beforeBalance = address(c).balance;
        uint256 beforeWinnersPot = c.winnersPot();

        // Attempt donate; capture whether it reverted
        bool reverted;
        try c.donate{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterBalance = address(c).balance;
        uint256 afterWinnersPot = c.winnersPot();

        // General rule asserted:
        // If donate call did not revert then the contract's balance must have decreased by exactly `amount`
        // (because donate forwards the full msg.value to whale), and winnersPot() (balance/2) must reflect that decrease.
        assert(reverted || (beforeBalance >= amount && beforeBalance - amount == afterBalance && beforeWinnersPot >= amount/2 && beforeWinnersPot - (amount/2) == afterWinnersPot));
    }

    // Allow this test contract to receive ETH so it can forward donations
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Call sequence: owner (this contract) opens to public, then calls donate{value: amount}().
    // We assert that if donate succeeds, winnersPot() (which is address(c).balance/2) does not increase.
    function run(uint256 amount) public payable {
        // Need some ETH to forward to donate
        require(address(this).balance >= amount);

        // This contract deployed c so it is owner and can open to public
        c.OpenToThePublic();

        // Observe before values
        uint256 beforeWinners = c.winnersPot();

        bool reverted;
        try c.donate{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterWinners = c.winnersPot();

        // General rule: if donate did not revert then winnersPot (balance/2) did not increase
        assert(reverted || afterWinners <= beforeWinners);
    }

    // Allow receiving ETH so the test can forward donations
    receive() external payable {}
}

contract InvMutTest {
    C c;
    address payable tester;

    constructor(C _c) {
        c = _c;
        tester = payable(address(this));
    }

    // We will: 1) make owner openToPublic and set bet limit and difficulty so play can be attempted;
    // 2) fund this contract so it can wager and donate; 3) call c.OpenToThePublic via c's owner (the deployer of c is owner => checker deploys c, but our contract is not owner, so we can't call onlyOwner functions).
    // Instead, rely on public surface only: we will assume c is already in some state. To make a valid property we observe winnersPot relation to balance after a winning play when this contract is the winner.

    // The single public test function. We take parameters to drive wager/play and Ether amounts.
    function run(uint256 betAmount, uint256 difficultySet, address whaleAddress) public payable {
        require(true);

        // Precondition: ensure this test contract has enough balance to send betAmount and to receive any payout.
        // The harness will provide msg.value to this call; move it to this contract's balance (already present).
        // Interact only with c's public API. We'll attempt to wager and then play; we must handle reverts.

        // Record balance of this test contract and contract c before actions
        uint256 beforeTesterBal = address(this).balance;
        uint256 beforeCbal = address(c).balance;
        uint256 beforeWinnersPot = c.winnersPot();

        bool wagerReverted;
        // Try to call wager with betAmount. Need to ensure we have funds in this contract to send.
        if (address(this).balance >= betAmount) {
            try c.wager{value: betAmount}() {
                wagerReverted = false;
            } catch {
                wagerReverted = true;
            }
        } else {
            // cannot send, mark reverted
            wagerReverted = true;
        }

        // Try to call play and observe if it reverted. play is expected to possibly revert if timestamps set to current block.
        bool playReverted;
        try c.play() {
            playReverted = false;
        } catch {
            playReverted = true;
        }

        // After interactions, read balances and winnersPot
        uint256 afterTesterBal = address(this).balance;
        uint256 afterCbal = address(c).balance;
        uint256 afterWinnersPot = c.winnersPot();

        // General rule to assert:
        // If play succeeded (did not revert) then winnersPot() must equal address(c).balance/2 and the tester's balance change must equal the payout amount (which is winnersPot before the transfer?), specifically tester received at most beforeCbal/2 and afterWinnersPot == afterCbal/2.
        // Formalize: If play did not revert then afterWinnersPot == afterCbal / 2 and (afterTesterBal - beforeTesterBal) <= beforeCbal / 2 + betAmount /*accounting for sending betAmount*/.

        assert(playReverted || (afterWinnersPot == afterCbal / 2 && (afterTesterBal >= beforeTesterBal ? afterTesterBal - beforeTesterBal <= beforeCbal / 2 + betAmount : true)));
    }

    receive() external payable {}
}

