contract InvMutTest {
    C c;
    address deployer;
    constructor(C _c) { c = _c; deployer = msg.sender; }

    // single public entry that tries to change owner-only settings from a non-owner and observes revert
    function run(uint256 newBetLimit, uint256 newDifficulty) public payable {
        // precondition: this contract is NOT the owner of c (the checker deploys c fresh and owner != this)
        // We cannot read owner directly (it's private) so we attempt the calls and record whether they revert.

        bool revertedAdjustBet;
        bool revertedAdjustDiff;

        // attempt AdjustBetAmounts as caller = this (InvMutTest)
        try c.AdjustBetAmounts(newBetLimit) {
            revertedAdjustBet = false;
        } catch {
            revertedAdjustBet = true;
        }

        // attempt AdjustDifficulty as caller = this (InvMutTest)
        try c.AdjustDifficulty(newDifficulty) {
            revertedAdjustDiff = false;
        } catch {
            revertedAdjustDiff = true;
        }

        // General rule: at least one of these owner-only calls must revert when invoked by a non-owner
        // (i.e., non-owner cannot successfully call both owner-only functions). This avoids assuming
        // which of the two reverts; it only requires that not both succeed.
        assert(revertedAdjustBet || revertedAdjustDiff);
    }

    // accept Ether if needed by potential calls (not required here)
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry that attempts to open the contract to public (must be done by owner),
    // then tries to wager with exactly the current betLimit and finally asserts the general invariant.
    function run(uint256 sendAmount) public payable {
        require(address(this).balance >= sendAmount);

        // Try to open to public as the deployer of c may be the owner; if this contract is not owner this may revert.
        // We don't treat that as failure for the rule; we only proceed to attempt a wager and observe outcomes.
        try c.OpenToThePublic() {
            // opened successfully
        } catch {
            // ignore if not owner
        }

        // Read the current bet limit before wagering (public getter currentBetLimit())
        uint256 currentLimit = c.currentBetLimit();

        // Only attempt to wager if we will send exactly the bet limit amount; otherwise the call would revert by design.
        bool wagerReverted;
        if (sendAmount == currentLimit && sendAmount > 0) {
            // ensure we have funds to send
            // Call wager with value = sendAmount
            try c.wager{value: sendAmount}() {
                wagerReverted = false;
            } catch {
                wagerReverted = true;
            }
        } else {
            // don't attempt wager because mismatch would trivially revert
            wagerReverted = true;
        }

        // Observe whether the contract records that this test contract has wagered
        bool recorded = c.hasPlayerWagered(address(this));

        // Observe the winners pot (balance/2) via public getter and the raw balance
        uint256 pot = c.winnersPot();
        uint256 bal = address(c).balance;

        // General rule:
        // If our wager call succeeded (did not revert) then hasPlayerWagered(this) must be true
        // and winnersPot() must equal address(c).balance/2 (i.e., pot*2 <= bal and pot*2 >= bal translated as equality via division semantics)
        // We express the pot equality as pot == bal / 2 which matches the contract's public winnersPot implementation.
        assert(wagerReverted || (recorded && pot == bal / 2));
    }

    receive() external payable {}
}

