contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We'll drive the contract so that a wager is placed in an earlier block and then play()
    // is attempted in a later block. Because we cannot advance blocks in this environment,
    // we instead rely on the property that whenever play() returns (i.e., does not revert)
    // and results in a Win (which triggers payout), the contract's balance after the call
    // is <= its balance before the call, and winnersPot() equals address(c).balance/2.
    // The single assert encodes this general rule for all inputs.

    function run(uint256 betLimit, address whaleAddr, uint256 sendDonateAmount) public payable {
        require(address(this).balance >= msg.value);
        // Note: the test receives no Ether from outside in this harness; callers may supply msg.value.
        // We perform only view calls to observe state before attempting operations that may revert.

        // Record the contract balance before any interactions
        uint256 balanceBefore = address(c).balance;
        uint256 winnersPotBefore = c.winnersPot();

        // Try to call donate to observe effect — this may revert if not openToPublic; capture revert flag
        bool donateReverted;
        try c.donate{value: sendDonateAmount}() {
            donateReverted = false;
        } catch {
            donateReverted = true;
        }

        // Try to call play(); it may revert or succeed. Capture whether it reverted.
        bool playReverted;
        try c.play() {
            playReverted = false;
        } catch {
            playReverted = true;
        }

        // Observe balances after the attempts
        uint256 balanceAfter = address(c).balance;
        uint256 winnersPotAfter = c.winnersPot();

        // General rule asserted: the contract's balance never increases as a result of payout (or play):
        // balanceAfter <= balanceBefore + (donate must have forwarded funds to whale on success, so donate can only decrease c's balance)
        // Also winnersPot() must equal address(c).balance/2.
        // We express a single assert combining both: winnersPotAfter == balanceAfter/2 AND balanceAfter <= balanceBefore.
        assert(winnersPotAfter == balanceAfter / 2 && balanceAfter <= balanceBefore);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We test the general rule about donate(uint256) forwarding value to the whale:
    // If donate() call (with value 'donateAmount') does not revert, then the contract's balance
    // must have decreased by at least donateAmount. We observe this via address(c).balance before/after
    // and also check winnersPot non-increase as an additional observable consequence.
    function run(uint256 donateAmount) public payable {
        // caller must fund this test contract so it can forward donateAmount
        require(address(this).balance >= donateAmount);

        // record balances before
        uint256 balanceBefore = address(c).balance;
        uint256 winnersPotBefore = c.winnersPot();

        // attempt donate with value donateAmount, capture whether it reverted
        bool donateReverted;
        try c.donate{value: donateAmount}() {
            donateReverted = false;
        } catch {
            donateReverted = true;
        }

        uint256 balanceAfter = address(c).balance;
        uint256 winnersPotAfter = c.winnersPot();

        // General rule: if donate succeeded then the contract's balance must decrease by at least donateAmount
        // and winnersPot (balance/2) cannot increase. If donate reverted, no guarantee, so only require the implication.
        assert(donateReverted || (balanceAfter + donateAmount <= balanceBefore && winnersPotAfter <= winnersPotBefore));
    }

    // Allow receiving Ether so the harness can fund this contract
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We need to be able to receive refunds/transfers from C
    receive() external payable {}

    // params: amount to send as the wager (must equal current bet limit to succeed),
    // and a flag to first open the contract to public by calling OpenToThePublic() as owner.
    // The test contract is the deployer/owner of c per the problem statement.
    function run(uint256 amount, bool callOpen) public payable {
        require(true);

        // optionally open to public (onlyOwner) — this contract deployed c so it is owner
        if (callOpen) {
            c.OpenToThePublic();
        }

        // read pre-state
        uint256 beforeBalance = c.ethBalance();
        bool beforeHas = c.hasPlayerWagered(address(this));
        uint256 betLimit = c.currentBetLimit();

        // to attempt to wager we must send 'amount' wei. Ensure this contract has funds.
        // The testing framework will provide Ether to this call if needed, but require to be safe.
        require(address(this).balance >= amount, "not enough balance to send");

        bool reverted;
        // call wager with value; this is the state-changing call and must be top-level
        try c.wager{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read post-state
        uint256 afterBalance = c.ethBalance();
        bool afterHas = c.hasPlayerWagered(address(this));

        // General rule to assert: If wager succeeded (did not revert) and the amount provided equals the contract's betLimit,
        // then the contract must record that this address has wagered (hasPlayerWagered == true),
        // and the contract balance must have increased by at least the betLimit amount.
        // (we use >= to be robust to other internal transfers that might also move funds)
        assert( (reverted || !(amount == betLimit) ) || (afterHas && afterBalance >= beforeBalance + betLimit) );
    }
}

