contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will: open to public, set a bet limit, fund the contract by sending Ether via the test contract
    // then perform a wager from this contract and later call play (in a later block simulated by using that wager's timestamp being earlier than current block isn't possible here),
    // but we must craft inputs to drive a successful play path. Because play() uses blockhash(timestamp) and randomSeed and difficulty,
    // we cannot reliably force the payout condition in general. Instead we assert a more general invariant: whenever play() returns (didn't revert),
    // the amount transferred to the winner equals the winnersPot() as observed immediately before payout and after the call the winnersPot() is <= previous winnersPot().
    // We observe this by comparing balances: when play() returns, the recipient (this contract) balance increase is <= previous winnersPot().

    // Single public test function as required
    function run(uint256 fundAmount, uint256 betLimit, uint256 difficulty, uint256 sendBet) public payable {
        require(true);

        // fund this test contract so it can send Ether to c
        // The checker will supply msg.value to this call; ensure we have enough to fund c and bet
        // We'll forward fundAmount to c to seed its balance; ensure this contract has enough
        if (fundAmount > 0) {
            require(address(this).balance >= fundAmount);
            // fund the target contract's balance via fallback
            (bool s1,) = address(c).call{value: fundAmount}("");
            require(s1);
        }

        // Owner-only calls: this InvMutTest is the deployer of c per problem statement, so it is owner
        c.OpenToThePublic();
        c.AdjustBetAmounts(betLimit);
        c.AdjustDifficulty(difficulty);

        // If sendBet > 0, ensure we have enough to wager; then call wager()
        bool wagerSucceeded = false;
        if (sendBet > 0) {
            require(address(this).balance >= sendBet);
            // call wager with exactly betLimit required by contract; use sendBet as the value transferred
            // If sendBet != betLimit this will revert; capture success via try/catch style using low-level call
            (bool ok,) = address(c).call{value: sendBet}(abi.encodeWithSignature("wager()"));
            wagerSucceeded = ok;
        }

        // Snapshot balances and winnersPot before attempting play
        uint256 cBalBefore = address(c).balance;
        uint256 winnersPotBefore = c.winnersPot();
        uint256 myBalBefore = address(this).balance;

        // Attempt to call play(); it may revert. Capture whether it reverted.
        bool reverted = false;
        (bool playOk,) = address(c).call(abi.encodeWithSignature("play()"));
        if (!playOk) {
            reverted = true;
        }

        uint256 cBalAfter = address(c).balance;
        uint256 winnersPotAfter = c.winnersPot();
        uint256 myBalAfter = address(this).balance;

        // If play returned (did not revert), then the contract may have paid out at most winnersPotBefore to the winner.
        // General rule to assert: if play did not revert then (my balance increase) <= winnersPotBefore and winnersPotAfter <= winnersPotBefore.
        // This is a general invariant about payouts: winnersPot cannot increase as a result of play(), and any individual recipient's balance increases by at most previous winnersPot.
        assert( reverted || ( (myBalAfter - myBalBefore) <= winnersPotBefore && winnersPotAfter <= winnersPotBefore) );
    }

    // allow receiving ETH from c when it pays out
    receive() external payable {}
}

