    constructor(C _c) { c = _c; }

    // We will take parameters to: open to public (none needed), set difficulty/betLimit via owner calls
    // but this contract is the deployer/owner per problem statement, so we can call owner-only functions.
    // Parameters: uint wagerAmount must equal the current bet limit to succeed; uint difficulty to set > 0.
    function run(uint256 wagerAmount, uint256 newDifficulty) public payable {
        require(newDifficulty > 1); // difficulty must be at least 2 for play() to compute modular
        // Ensure this contract opened the contract to public so its calls pass the isOpenToPublic modifier
        c.OpenToThePublic();
        // Set difficulty and bet limit to controlled values
        c.AdjustDifficulty(newDifficulty);
        c.AdjustBetAmounts(wagerAmount);

        // Make sure this test contract has sufficient balance to send the wager
        require(address(this).balance >= wagerAmount);

        // Read observable before-values
        uint256 beforeWinnersPot = c.winnersPot();
        bool revertedWager;
        try c.wager{value: wagerAmount}() {
            revertedWager = false;
        } catch {
            revertedWager = true;
        }

        // If wager reverted then play cannot proceed as player, so we will attempt play and record revert
        bool revertedPlay;
        try c.play() {
            revertedPlay = false;
        } catch {
            revertedPlay = true;
        }

        uint256 afterWinnersPot = c.winnersPot();
        bool hasWagerAfter = c.hasPlayerWagered(address(this));

        // General rule: if play() returned (did not revert) then hasPlayerWagered(this) must be false
        // and winnersPot() after play() must be <= winnersPot() before play().
        assert((revertedPlay) || (!hasWagerAfter && afterWinnersPot <= beforeWinnersPot));
    }

    receive() external payable {}
}
